import unittest
from candidate import change_base


class TestChangeBaseNormalCases(unittest.TestCase):
    def test_change_base_8_to_3(self):
        self.assertEqual(change_base(8, 3), '22')

    def test_change_base_8_to_2(self):
        self.assertEqual(change_base(8, 2), '1000')

    def test_change_base_7_to_2(self):
        self.assertEqual(change_base(7, 2), '111')

    def test_change_base_10_to_2(self):
        self.assertEqual(change_base(10, 2), '1010')

    def test_change_base_10_to_10(self):
        self.assertEqual(change_base(10, 10), '10')

    def test_change_base_1_to_2(self):
        self.assertEqual(change_base(1, 2), '1')

    def test_change_base_1_to_10(self):
        self.assertEqual(change_base(1, 10), '1')

    def test_change_base_2_to_2(self):
        self.assertEqual(change_base(2, 2), '10')

    def test_change_base_4_to_3(self):
        self.assertEqual(change_base(4, 3), '11')

    def test_change_base_100_to_10(self):
        self.assertEqual(change_base(100, 10), '100')

    def test_change_base_255_to_2(self):
        self.assertEqual(change_base(255, 2), '11111111')

    def test_change_base_100_to_5(self):
        self.assertEqual(change_base(100, 5), '400')

    def test_change_base_9_to_10(self):
        self.assertEqual(change_base(9, 10), '9')

    def test_change_base_20_to_3(self):
        self.assertEqual(change_base(20, 3), '202')

    def test_change_base_30_to_7(self):
        self.assertEqual(change_base(30, 7), '42')

    def test_change_base_50_to_8(self):
        self.assertEqual(change_base(50, 8), '62')

    def test_change_base_63_to_9(self):
        self.assertEqual(change_base(63, 9), '70')

    def test_change_base_1_to_9(self):
        self.assertEqual(change_base(1, 9), '1')

    def test_change_base_99_to_10(self):
        self.assertEqual(change_base(99, 10), '99')

    def test_change_base_large_number_to_binary(self):
        self.assertEqual(change_base(1024, 2), '10000000000')


class TestChangeBaseEdgeCases(unittest.TestCase):
    def test_change_base_zero_returns_empty_string(self):
        self.assertEqual(change_base(0, 2), '')

    def test_change_base_zero_base_10(self):
        self.assertEqual(change_base(0, 10), '')

    def test_change_base_zero_base_5(self):
        self.assertEqual(change_base(0, 5), '')

    def test_change_base_negative_returns_empty_string(self):
        self.assertEqual(change_base(-5, 2), '')

    def test_change_base_negative_one_base_10(self):
        self.assertEqual(change_base(-1, 10), '')

    def test_change_base_one_digit_same_as_base_minus_one(self):
        self.assertEqual(change_base(8, 9), '8')

    def test_change_base_returns_string_type(self):
        self.assertIsInstance(change_base(10, 2), str)


class TestChangeBaseErrorCases(unittest.TestCase):
    def test_change_base_zero_base_raises_zero_division_error(self):
        with self.assertRaises(ZeroDivisionError):
            change_base(10, 0)

    def test_change_base_none_x_raises_type_error(self):
        with self.assertRaises(TypeError):
            change_base(None, 2)

    def test_change_base_none_base_raises_type_error(self):
        with self.assertRaises(TypeError):
            change_base(10, None)

    def test_change_base_string_x_raises_type_error(self):
        with self.assertRaises(TypeError):
            change_base("8", 2)

    def test_change_base_string_base_raises_type_error(self):
        with self.assertRaises(TypeError):
            change_base(8, "2")

    def test_change_base_both_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            change_base(None, None)


class TestChangeBaseBoundaryConditions(unittest.TestCase):
    def test_change_base_minimum_positive_x(self):
        self.assertEqual(change_base(1, 2), '1')

    def test_change_base_x_equals_base(self):
        self.assertEqual(change_base(5, 5), '10')

    def test_change_base_x_just_below_base(self):
        self.assertEqual(change_base(4, 5), '4')

    def test_change_base_x_equals_base_squared_minus_one(self):
        self.assertEqual(change_base(8, 3), '22')

    def test_change_base_base_2_only_digits_0_and_1(self):
        result = change_base(42, 2)
        self.assertTrue(all(c in '01' for c in result))

    def test_change_base_base_3_only_digits_0_1_2(self):
        result = change_base(100, 3)
        self.assertTrue(all(c in '012' for c in result))

    def test_change_base_base_9_only_digits_0_through_8(self):
        result = change_base(1000, 9)
        self.assertTrue(all(c in '012345678' for c in result))


if __name__ == '__main__':
    unittest.main()
